import {validWorkbookReport,completeWorkbook,workbookQuestions,workbookChoices} from './innerly-v1-model.mjs?v=mh-14';
import {reportSnapshot,reportAreas,reportCategories,areaGraph,icon,escapeHTML as esc} from './report-concept-view.mjs?v=5';
import {questionExplorerMarkup,benchmarkReading,responseRuler} from './question-explorer.mjs?v=4';

const say=(l,en,hi)=>l==='hi'?hi:en;
export const usesPersonalReport=report=>validWorkbookReport(report)&&completeWorkbook(report.answers);
export function personalQuestionMarkup(snapshot,index,l='en'){
 const item=snapshot.items[index],labels=reportCategories(l),design=reportAreas(l)[Math.floor(index/6)];
 return `<div class="dialog-top"><span class="small-label">${design.name} · ${item.id}</span><button class="close-dialog" aria-label="${say(l,'Close question','सवाल बंद करें')}">×</button></div><div class="question-dialog-grid"><div class="question-answer"><p class="question-number">${say(l,`QUESTION ${index+1} OF 36`,`सवाल ${index+1} / 36`)}</p><h2 id="personal-question-title">${esc(workbookQuestions[index].texts[l])}</h2><div class="personal-recorded-answer" style="--question-color:${labels[item.category].color}"><span class="small-label">${say(l,'YOUR RECORDED ANSWER','आपका दिया हुआ जवाब')}</span>${responseRuler(item,l)}<strong>${esc(item.response)}</strong><span class="category-pill ${item.category}">${labels[item.category].short}</span></div><p class="fine-print">${say(l,'This is the answer you submitted. The report keeps it unchanged.','यह आपका जमा किया हुआ जवाब है। Report इसे बदलती नहीं है।')}</p><div class="question-navigation"><button data-personal-prev${index===0?' disabled':''}>${say(l,'← Previous question','← पिछला सवाल')}</button><button data-personal-next${index===35?' disabled':''}>${say(l,'Next question →','अगला सवाल →')}</button></div></div><div class="question-reading"><span class="small-label">${say(l,'WHAT THIS ANSWER SUGGESTS','इस जवाब से क्या समझें')}</span><h3>${esc(item.label)}</h3><p class="reading-note">${say(l,`You selected “${esc(item.response)}”. This is a reflection on this statement, not a diagnosis.`,`आपने “${esc(item.response)}” चुना। यह इस कथन पर विचार है, diagnosis नहीं।`)}</p><div class="reading-step"><span>${say(l,'ONE SMALL STEP','एक छोटा कदम')}</span><p>${esc(item.step)}</p></div><div class="reading-benefit"><span>${say(l,'WHAT THIS COULD HELP WITH','इससे किस बात में मदद मिल सकती है')}</span><p>${esc(item.benefit)}</p></div></div></div><details class="personal-benchmark"><summary>${say(l,'See a simulated population comparison · mock data','काल्पनिक population तुलना देखें · mock डेटा')}</summary>${benchmarkReading(index,item.value,l)}</details>`;
}
export function personalReportMarkup(report,history=[],language='en'){
 if(!usesPersonalReport(report))throw new Error('A completed current-questionnaire report is required.');
 const l=language==='hi'?'hi':'en',snapshot=reportSnapshot(report.answers,l),design=reportAreas(l),labels=reportCategories(l),keys=Object.keys(labels);
 const saved=history.some(r=>r.id===report.id),date=new Date(report.createdAt).toLocaleDateString(l,{day:'numeric',month:'long',year:'numeric'});
 let offset=0;
 return `<div data-personal-report lang="${l}"><div class="report-layout"><aside class="report-sidebar"><div class="sidebar-inner"><p class="small-label">${say(l,'YOUR REPORT','आपकी रिपोर्ट')}</p><nav aria-label="${say(l,'Report sections','रिपोर्ट के हिस्से')}"><a class="overview-link" href="#overview">${icon('orbit')}${say(l,'The big picture','पूरी तस्वीर')}</a><p class="small-label sidebar-subtitle">${say(l,'SIX AREAS OF YOU','आपके छह पहलू')}</p>${design.map((a,i)=>`<a href="#area-${i}" style="--area:${a.color}"><span class="nav-number">0${i+1}</span>${a.name}</a>`).join('')}<a class="plan-nav" href="#next-steps">${icon('leaf')}${say(l,'Your next steps','आपके अगले कदम')}</a><a class="questions-nav" href="#question-insights">${icon('spark')}${say(l,'All 36 answers','सभी 36 जवाब')}</a></nav><div class="sidebar-note">${icon('spark')}<p>${say(l,'A moment in time.<br>Room to keep growing.','इस पल की एक झलक।<br>आगे बढ़ने की गुंजाइश।')}</p></div><button class="back-link" data-action="home">${say(l,'← Back to Innerly','← Innerly पर वापस')}</button></div></aside>
 <div class="report-main" id="report"><section class="report-intro" id="overview"><div class="intro-meta"><span class="sample-badge"><i></i>${say(l,'YOUR PERSONAL REFLECTION','आपकी व्यक्तिगत REFLECTION')}</span><span>${esc(date)}</span></div><h1>${say(l,'Your mind,<br><span>in perspective.</span>','आपका मन,<br><span>एक नई नज़र से।</span>')}<span class="title-spark" aria-hidden="true">✳</span></h1><div class="intro-bottom"><p>${say(l,'Built from your 36 answers.<br>Your patterns, your strengths, your next steps.','आपके 36 जवाबों से बनी।<br>आपके पैटर्न, मजबूतियाँ और अगले कदम।')}</p><div class="report-stamp"><span>${say(l,'COMPLETED CHECK-IN','पूरा CHECK-IN')}</span><strong>36 <i>/ 36</i></strong></div></div></section>
 <section class="sample-toolbar personal-report-actions"><div><span class="live-dot"></span><strong>${say(l,'Your answers. Your report.','आपके जवाब। आपकी रिपोर्ट।')}</strong><span>${say(l,saved?'Saved automatically in this browser.':'Not saved yet. Keep this page open.',saved?'इस browser में अपने आप सेव है।':'अभी सेव नहीं है। यह पेज खुला रखें।')}</span></div><div class="personal-action-buttons"><button class="plain-button" data-action="save"${saved?' disabled':''}>${icon('check')}${say(l,saved?'Saved on this device':'Save on this device',saved?'इस device पर सेव है':'इस device पर सेव करें')}</button><button class="primary-button" data-action="print">${icon('print')}${say(l,'Print / PDF','Print / PDF')}</button></div></section><p id="mh-report-status" role="status"></p>
 <section class="overview-grid" aria-label="${say(l,'Report overview','रिपोर्ट की झलक')}"><article class="summary-card"><div class="card-top"><span class="small-label">${say(l,'YOUR RESPONSE LANDSCAPE','आपके जवाबों की तस्वीर')}</span>${icon('orbit')}</div><h2>${say(l,'Your starting point.','आपकी शुरुआत।')}</h2><p>${say(l,'What supports you, what varies, and where you might want to begin.','क्या मददगार है, क्या बदलता है, और कहाँ से शुरुआत कर सकते हैं।')}</p><div class="donut-wrap"><svg class="donut-chart" viewBox="0 0 260 260" role="img" aria-label="${esc(keys.map(k=>`${labels[k].name}: ${snapshot.counts[k]}`).join(', '))}"><circle class="donut-track" cx="130" cy="130" r="100"/>${keys.map(k=>{const count=snapshot.counts[k],start=offset,length=Math.max(0,count/36*100-1.7);offset+=count/36*100;return `<circle cx="130" cy="130" r="100" pathLength="100" fill="none" stroke="${labels[k].color}" stroke-dasharray="${length} ${100-length}" stroke-dashoffset="${-start}" transform="rotate(-90 130 130)" opacity="${count?1:0}"/>`;}).join('')}<text class="donut-total" x="130" y="130" text-anchor="middle">36</text><text class="donut-caption" x="130" y="153" text-anchor="middle">${say(l,'your recorded answers','आपके दिए हुए जवाब')}</text></svg></div><div class="summary-legend">${keys.map(k=>`<button data-personal-group="${k}"><span class="legend-dot" style="background:${labels[k].color}"></span><span>${labels[k].name}</span><b>${snapshot.counts[k]}</b></button>`).join('')}</div><p class="fine-print">${say(l,'Response counts, not a mental-health score or world percentile.','जवाबों की गिनती; mental-health score या world percentile नहीं।')}</p></article>
 <article class="landscape-card"><div class="card-top"><span class="small-label">${say(l,'SIX-AREA OVERVIEW','छह पहलुओं की झलक')}</span><span class="small-chip">36 / 36</span></div><h2>${say(l,'Different parts.<br>One connected picture.','अलग-अलग पहलू।<br>एक जुड़ी हुई तस्वीर।')}</h2><div class="stack-legend">${keys.map(k=>`<span><i style="background:${labels[k].color}"></i>${labels[k].short}</span>`).join('')}</div><div class="landscape-bars">${snapshot.areas.map((a,i)=>`<button class="landscape-row" data-area-jump="${i}" aria-label="${say(l,'Explore','देखें')} ${design[i].name}"><span class="landscape-row-name">${icon(design[i].icon)}${design[i].name}<span>6 ${say(l,'answers','जवाब')}</span></span><span class="stack-track">${keys.map(k=>{const n=a.items.filter(item=>item.category===k).length;return `<span style="width:${n/6*100}%;background:${labels[k].color}"${n?'':' hidden'} title="${n} ${labels[k].name}"><b>${n||''}</b></span>`;}).join('')}</span></button>`).join('')}</div><div class="chart-footnote">${icon('spark')}${say(l,'Each overview keeps the six original answers.','हर झलक में छह मूल जवाब शामिल हैं।')}</div></article></section>
 <section class="area-section" id="six-areas"><div class="section-heading"><div><p class="small-label">${say(l,'THE SIX CONNECTED AREAS','छह जुड़े हुए पहलू')}</p><h2>${say(l,'A little context for each area.','हर पहलू को थोड़ा और समझें।')}</h2><p>${say(l,'Your exact response frequency, question by question.','हर सवाल पर आपके जवाब की असली आवृत्ति।')}</p></div><div class="chart-mode" role="group" aria-label="${say(l,'Chart display','ग्राफ का प्रकार')}"><button data-chart-mode="bars" aria-pressed="true">▥ ${say(l,'Bars','Bars')}</button><button data-chart-mode="line" aria-pressed="false">⌁ ${say(l,'Lines','Lines')}</button></div></div><div class="areas-grid">${snapshot.areas.map((a,i)=>{const support=a.supports.find(item=>item.value>=3)||a.supports[0],focus=a.focuses[0]||a.varies[0];return `<article class="area-card" id="area-${i}" style="--area:${design[i].color};--area-light:${design[i].light}"><div class="area-card-top"><div class="area-icon">${icon(design[i].icon)}</div><span>0${i+1} / 06</span><span class="area-count">6 ${say(l,'answers','जवाब')}</span></div><h3>${design[i].name}</h3><p class="area-caption">${design[i].caption}</p>${areaGraph(a,i,l)}<div class="area-insights"><div class="insight support"><span>${icon('spark')}${labels.support.short}</span><p>${support?esc(`${support.label} · ${support.response}`):say(l,'Explore your answers for context.','अपने जवाबों को विस्तार से देखें।')}</p></div><div class="insight ${focus?.category||'varies'}"><span>${icon('branch')}${focus?labels[focus.category].short:say(l,'Keep exploring','समझते रहें')}</span><p>${focus?esc(`${focus.label} · ${focus.response}`):say(l,'Keep noticing what helps.','मददगार बातों पर ध्यान देते रहें।')}</p></div></div><button class="area-open" data-question="${a.next.index}">${say(l,'Explore your next step','अपना अगला कदम देखें')}${icon('arrow')}</button></article>`;}).join('')}</div><p class="fine-print graph-note">${say(l,'Higher frequency is not always better. The meaning depends on the question. Lines connect separate questions, not progress over time.','अधिक आवृत्ति हमेशा बेहतर नहीं है। अर्थ सवाल पर निर्भर करता है। Lines अलग सवालों को जोड़ती हैं, समय के साथ प्रगति को नहीं।')}</p></section>
 <section class="next-section" id="next-steps"><div class="section-heading"><div><p class="small-label">${say(l,'FROM YOUR ANSWERS TO YOUR NEXT STEP','आपके जवाबों से अगले कदम तक')}</p><h2>${say(l,'Start with something small.','एक छोटे कदम से शुरू करें।')}</h2><p>${say(l,'One starting point per area. Every question has its own step when you open it.','हर पहलू के लिए एक शुरुआत। हर सवाल खोलने पर उसका अपना कदम भी मिलेगा।')}</p></div><span class="plan-counter"><b id="tried-count">0</b> / 6 ${say(l,'tried','आज़माए')}</span></div><div class="plan-list">${snapshot.areas.map((a,i)=>{const item=a.next;return `<article class="plan-item" style="--area:${design[i].color};--area-light:${design[i].light}"><div class="plan-icon">${icon(design[i].icon)}</div><div class="plan-copy"><span class="small-label">${design[i].name} · ${item.id}</span><h3>${esc(item.label)}</h3><p>${esc(item.step)}</p><div class="plan-benefit">${icon('arrow')}<span>${esc(item.benefit)}</span></div></div><label class="try-check"><input type="checkbox" data-personal-tried="${item.id}" aria-label="${say(l,'Mark as tried','आज़माया हुआ चिह्नित करें')}: ${esc(item.label)}"><span>${icon('check')}</span><b>${say(l,'Try this','आज़माएँ')}</b></label></article>`;}).join('')}</div><p class="fine-print">${say(l,'Possible benefits are not guaranteed outcomes. Tried activities stay in this open page only.','संभावित लाभ की गारंटी नहीं है। आज़माई गई गतिविधियों के निशान केवल इस खुले पेज में रहते हैं।')}</p></section>
 ${questionExplorerMarkup(snapshot,report,history,l)}
 <section class="report-method"><details><summary>${say(l,'Your complete answer record','आपके सभी जवाब')} <span>${say(l,'36 answers, steps and possible benefits','36 जवाब, कदम और संभावित लाभ')}</span></summary><div class="method-copy"><p>${say(l,'This reflection describes your answers using editorial guidance, not validated diagnostic scores. The optional world-comparison preview uses 100 fictional answers per question, not real-world norms. No information is sent to a comparison service.','यह reflection संपादकीय मार्गदर्शन से आपके जवाब समझाती है, validated diagnostic score नहीं देती। वैकल्पिक world-comparison preview हर सवाल के 100 काल्पनिक जवाब इस्तेमाल करता है, असली दुनिया का benchmark नहीं। किसी comparison service को जानकारी नहीं भेजी जाती।')}</p></div><div class="response-table-wrap"><table><caption>${say(l,'All 36 submitted answers','सभी 36 जमा जवाब')}</caption><thead><tr><th>${say(l,'Question','सवाल')}</th><th>${say(l,'Statement','कथन')}</th><th>${say(l,'Answer','जवाब')}</th><th>${say(l,'Reflection & next step','समझ और अगला कदम')}</th></tr></thead><tbody>${snapshot.items.map(item=>`<tr><td>${item.id}</td><td>${esc(workbookQuestions[item.index].texts[l])}</td><td>${esc(item.response)}</td><td><b>${labels[item.category].short}</b><p>${esc(item.step)}</p><p>${say(l,'Could help with','इसमें मदद मिल सकती है')}: ${esc(item.benefit)}</p></td></tr>`).join('')}</tbody></table></div></details></section><section class="closing-note"><div>${icon('spark')}<h2>${say(l,'A starting point.<br><span>More to discover about you.</span>','एक शुरुआत।<br><span>खुद को और समझने की।</span>')}</h2></div><button class="primary-button" data-action="begin">${say(l,'Start My Test','अपना टेस्ट शुरू करें')}${icon('arrow')}</button></section><footer class="report-footer"><span>innerly.</span><span>${say(l,saved?'Saved in this browser · Not synced to an account':'Unsaved report · Save or print to keep it',saved?'इसी browser में सेव · खाते से sync नहीं':'Report सेव नहीं है · रखने के लिए सेव या print करें')}</span></footer></div></div><dialog id="personal-question-dialog" aria-labelledby="personal-question-title"></dialog></div>`;
}
